import type { Category, Equipment, Exercise, Muscle, TrackingMode } from '@/domain/types';
import { slug } from '@/domain/util';

/**
 * Second part of the library. Rows are compact: muscles are space separated, steps and form cues
 * are "|" separated. tests/unit/domain.test.ts validates every value, since strings aren't type-checked here.
 * Ids come from names, so names must not change once shipped.
 */
const row = (mode: TrackingMode) => (name: string, primary: string, secondary: string, equipment: string, category: string, steps: string, form: string): Exercise => ({
  id: slug(name), name, mode,
  primary: primary.split(' ') as Muscle[],
  secondary: (secondary ? secondary.split(' ') : []) as Muscle[],
  equipment: equipment as Equipment, category: category as Category,
  steps: steps.split('|'), form: form.split('|'),
});
const s = row('strength'), b = row('bodyweight'), t = row('timed'), c = row('cardio');

